ee:message.ee:set-payload:
%dw 2.0
output application/json

fun charItem(nombre, valor) = {
	Nombre: nombre,
	Valor: (valor default "") as String
}

fun formatExpeditionDate(d) =
	if (d == null or d == "")
		""
	else if (d is Date)
		d as String {format: "dd/MM/yyyy"}
	else if ((d is DateTime) or (d is LocalDateTime))
		(d as Date) as String {format: "dd/MM/yyyy"}
	else do {
		var s = d as String
		---
		if (s contains "/")
			s[0 to 9]
		else
			(s[0 to 9] as Date {format: "yyyy-MM-dd"}) as String {format: "dd/MM/yyyy"}
	}

fun toCaracteristica(item) = {
	Nombre: item.name default item.Nombre default "",
	Valor: (item.value default item.Valor default "") as String
}

fun findChar(list, name) =
	(list filter ((c) -> upper(c.Nombre default "") == upper(name)))[0]

var customer = payload.customer default {}
var context = (customer.characteristics default []) map (item) -> toCaracteristica(item)

var catalog = [
	"APELLIDO",
	"NOMBRE",
	"TRAMITE",
	"USUARIO",
	"CANAL",
	"PROVEEDOR",
	"CIUDAD",
	"DEPARTAMENTO",
	"SISTEMA ORIGEN",
	"MODELO",
	"PORTAL",
	"NUMERO_CONTACTO",
	"TIPO",
	"ESTRATO",
	"CALCULAR_SCORE"
]

fun fromField(name) =
	name match {
		case "APELLIDO" -> customer.firstLastName
		case "MODELO" -> payload.adviser
		case "PORTAL" -> payload.portal
		else -> null
	}

fun resolveValue(name) = do {
	var fieldValue = fromField(name)
	var contextValue = findChar(context, name).Valor
	---
	if (fieldValue != null and fieldValue != "")
		fieldValue as String
	else if (contextValue != null)
		contextValue as String
	else if (name == "CALCULAR_SCORE")
		"TRUE"
	else
		""
}

---
{
	Tipo_Documento: customer.documentType default "",
	Numero_Documento: customer.documentNumber default "",
	Primer_Apellido: customer.firstLastName default "",
	Fecha_Expedicion: formatExpeditionDate(customer.dateExpedition),
	Razon_Social: customer.businessName default "",
	Caracteristicas: catalog map (name) -> charItem(name, resolveValue(name))
}
